using SixLabors.ImageSharp.Formats;
using SixLabors.ImageSharp.Formats.Av1;
using SixLabors.ImageSharp.Formats.Av1.Bitstream;
using SixLabors.ImageSharp.PixelFormats;

namespace SixLabors.ImageSharp.Codecs.Av1.Tests;

/// <summary>
/// Validates multi-frame decode of a real two-frame all-intra AV1/IVF clip: both coded frames are
/// reconstructed and surface as separate frames in the decoded image. The second frame's luma is
/// compared against dav1d's full-pipeline reference (reconstruction, deblocking and CDEF) to confirm
/// the per-frame decode is correct, not just the first frame.
/// </summary>
public class Av1MultiFrameDecodeTests
{
    private const string TinyIvfBase64 = "REtJRgAAIABBVjAxQABAAB4AAAABAAAAAgAAAAAAAAAlAAAAAAAAAAAAAAASAAoKAAAAAq//m18wCDIVEADQAAACiAAAH/gZXiPv/K/uo02mJQAAAAEAAAAAAAAAEgAKCgAAAAKv/5tfMAgyFRAA0AAAAogAAB/4GV4j7/y47H02mA==";
    private const string Frame1LumaBase64 = "";

    [Fact]
    public void DecodeAllFrames_SecondFrame_MatchesDav1d()
    {
        using MemoryStream stream = new(Convert.FromBase64String(TinyIvfBase64));
        System.Collections.Generic.List<Av1TileDecoder> frames = Av1DecoderCore.DecodeAllFrames(stream);

        Assert.Equal(2, frames.Count);
        Assert.Equal(Convert.FromBase64String(Frame1LumaBase64), frames[1].Luma.Samples);
    }

    [Fact]
    public void Decode_ProducesTwoImageFrames()
    {
        byte[] ivf = Convert.FromBase64String(TinyIvfBase64);
        using MemoryStream stream = new(ivf);
        using Image<Rgba32> image = Av1Decoder.Instance.Decode<Rgba32>(new DecoderOptions(), stream);

        Assert.Equal(2, image.Frames.Count);
        Assert.Equal(64, image.Width);
        Assert.Equal(64, image.Height);
    }
}
